Running command: cd /workspace/repo-vul/src-vul/curl && python3 - << 'EOF'
import re
with open('lib/pingpong.c') as f:
    content = f.read()
# Add debug print before the memcpy in cache path
old = """      if((ptr + pp->cache_size) > (buf + data->set.buffer_size + 1)) {
        failf(data, "cached response data too big to handle");
        return CURLE_RECV_ERROR;
      }
      memcpy(ptr, pp->cache, pp->cache_size);"""
new = """      if((ptr + pp->cache_size) > (buf + data->set.buffer_size + 1)) {
        failf(data, "cached response data too big to handle");
        return CURLE_RECV_ERROR;
      }
      fprintf(stderr, "DBG cache: ptr_offset=%ld cache_size=%zu nread=%zu buffer_size=%zu perline=%ld linestart_offset=%ld\\n", (long)(ptr-buf), pp->cache_size, pp->nread_resp, data->set.buffer_size, (long)perline, (long)(pp->linestart_resp-buf));
      memcpy(ptr, pp->cache, pp->cache_size);"""
assert old in content
content = content.replace(old, new)
with open('lib/pingpong.c','w') as f:
    f.write(content)
print("patched")
EOF

